css:
.sparksim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2440;
    background: linear-gradient(160deg, #fff7ef 0%, #fdeede 45%, #f6e7ff 100%);
    border-radius: 18px;
}

.sparksim-container * {
    box-sizing: border-box;
}

.sparksim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(125deg, #6d28d9 0%, #d6336c 55%, #f97316 100%);
    color: #fff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 38px rgba(109, 40, 217, 0.30);
}

.sparksim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fffaf3;
}

.sparksim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #fff3cf;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.sparksim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #fdeede;
}

.sparksim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5b8a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.sparksim-period-counter #currentDay,
.sparksim-period-counter #maxPeriods {
    font-weight: 800;
    color: #d6336c;
}

.sparksim-round-name {
    background: rgba(214, 51, 108, 0.12);
    color: #d6336c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.sparksim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b45309;
    background: rgba(249, 115, 22, 0.14);
    border: 1px solid rgba(249, 115, 22, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.sparksim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.sparksim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #f0e3d6;
    box-shadow: 0 6px 18px rgba(109, 40, 217, 0.08);
    border-top: 4px solid #cbb6e6;
}

.sparksim-card-novelty { border-top-color: #f97316; }
.sparksim-card-useful { border-top-color: #14b8a6; }
.sparksim-card-motivation { border-top-color: #d6336c; }
.sparksim-card-proto { border-top-color: #6d28d9; }

.sparksim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7aa3;
}

.sparksim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2440;
    font-variant-numeric: tabular-nums;
}

.sparksim-card-novelty .sparksim-value { color: #ea580c; }
.sparksim-card-useful .sparksim-value { color: #0d9488; }
.sparksim-card-motivation .sparksim-value { color: #d6336c; }
.sparksim-card-proto .sparksim-value { color: #6d28d9; }

.sparksim-sublabel {
    font-size: 0.76rem;
    color: #9a8cb0;
    line-height: 1.35;
}

.sparksim-card-low .sparksim-value { color: #dc2626; }
.sparksim-card-low { border-top-color: #dc2626; }
.sparksim-card-high { border-top-color: #16a34a; }
.sparksim-card-high .sparksim-value { color: #16a34a; }

.sparksim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #f0e3d6;
    color: #4a3f63;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(109, 40, 217, 0.06);
}

.sparksim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #6d28d9;
}

.sparksim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #f97316;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(249, 115, 22, 0.10);
}

.sparksim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.sparksim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #6d28d9;
    margin-bottom: 6px;
}

.sparksim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3f63;
}

.sparksim-briefing-text strong { color: #d6336c; }
.sparksim-briefing-text em { color: #b45309; font-style: italic; }

.sparksim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #f0e3d6;
    box-shadow: 0 6px 18px rgba(109, 40, 217, 0.08);
}

.sparksim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b2440;
    border-bottom: 2px solid #f3e9f7;
    padding-bottom: 8px;
}

.sparksim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3d3357;
    margin: 14px 0 6px;
}

.sparksim-container select,
.sparksim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #e2d2ec;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdfbff;
    color: #2b2440;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.sparksim-container select:focus,
.sparksim-container input[type="number"]:focus {
    outline: none;
    border-color: #6d28d9;
    box-shadow: 0 0 0 3px rgba(109, 40, 217, 0.16);
}

.sparksim-container select option {
    background-color: #ffffff;
    color: #2b2440;
}

.sparksim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f97316;
}

.sparksim-range-readout,
.sparksim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5b8a;
    margin-top: 4px;
}

.sparksim-range-readout span:last-child,
.sparksim-alloc-readout span:nth-child(2) {
    color: #d6336c;
    font-weight: 800;
}

.sparksim-hint {
    font-size: 0.8rem;
    color: #9a8cb0;
    margin-top: 4px;
    line-height: 1.4;
}

.sparksim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.sparksim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fdf6ff;
    border: 1px solid #ecdcf3;
    border-radius: 9px;
    padding: 8px 12px;
}

.sparksim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a3f63;
}

.sparksim-alloc-row input[type="number"] {
    width: 84px;
    flex: 0 0 84px;
}

.sparksim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.sparksim-container .btn-primary {
    background: linear-gradient(135deg, #6d28d9 0%, #d6336c 55%, #f97316 100%);
    border: none;
    color: #fffaf3;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 22px rgba(214, 51, 108, 0.32);
}

.sparksim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.sparksim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #e2d2ec;
    color: #6b5b8a;
    background: transparent;
}

.sparksim-coach {
    background: linear-gradient(160deg, #2b1d4d 0%, #3a1d3d 100%);
    color: #f3eafc;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(43, 29, 77, 0.30);
}

.sparksim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #fbbf24;
    margin-bottom: 8px;
}

.sparksim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.sparksim-coach-body strong { color: #fbbf24; }
.sparksim-coach-body em { color: #f9a8d4; font-style: italic; }

.sparksim-history,
.sparksim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #f0e3d6;
    box-shadow: 0 6px 18px rgba(109, 40, 217, 0.08);
}

.sparksim-history h3,
.sparksim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b2440;
}

.sparksim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3f63;
}

.sparksim-container table#usfHistoryTable th {
    background: #f6eefb;
    color: #6d28d9;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ecdcf3;
}

.sparksim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f3ebf8;
    color: #4a3f63;
}

.sparksim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdf9ff;
}

.sparksim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .sparksim-container {
        padding: 14px;
    }
    .sparksim-header h1 {
        font-size: 1.7rem;
    }
    .sparksim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .sparksim-value {
        font-size: 2rem;
    }
    .sparksim-clock {
        margin-left: 0;
    }
    .sparksim-period-counter {
        font-size: 0.88rem;
    }
    .sparksim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .sparksim-alloc-row {
        flex-wrap: wrap;
    }
    .sparksim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .sparksim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .sp-cm-*, purple/magenta/orange) ── */
.sp-cm { margin-top: 8px; }
.sp-cm-incomplete { text-align: center; color: #4a3f63; font-size: 1rem; padding: 18px; }
.sp-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.sp-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #6d28d9 0%, #d6336c 60%, #f97316 130%); color: #fffaf3; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(45, 36, 64, 0.3); }
.sp-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.sp-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.sp-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #ffe0c2; }
.sp-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fffaf3; border: 1px solid #f0e3d6; border-left: 5px solid #6d28d9; border-radius: 14px; padding: 16px 20px; }
.sp-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b5b8a; }
.sp-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #6d28d9; line-height: 1.15; }
.sp-cm-section { margin-bottom: 16px; }
.sp-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b5b8a; margin-bottom: 8px; }
.sp-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.sp-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.sp-cm-ok { background: rgba(47, 158, 110, 0.14); color: #2f8f63; border-color: rgba(47, 158, 110, 0.42); }
.sp-cm-no { background: rgba(214, 51, 108, 0.12); color: #d6336c; border-color: rgba(214, 51, 108, 0.42); }
.sp-cm-ico { font-weight: 800; }
.sp-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.sp-cm-kpi { background: #fffaf3; border: 1px solid #f0e3d6; border-top: 4px solid #d6336c; border-radius: 12px; padding: 14px 12px; text-align: center; }
.sp-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #6d28d9; line-height: 1; }
.sp-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #2b2440; }
.sp-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #6b5b8a; }
.sp-cm-insights { margin: 0; padding-left: 18px; color: #2b2440; }
.sp-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .sp-cm-head { flex-direction: column; } .sp-cm-score { min-width: 0; } }

