(function() {
    'use strict';

    class SparkAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Spark the Team`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Vanta Play Ltd).
            this.DEV_BUDGET = 2.4;        // GBP 2.4M development budget
            this.FRONT_END = 10;          // ~10 front-end (ideation) weeks
            this.BUILD_WEEKS = 18;        // fixed downstream engineering build
            this.IFA_WEEK = 34;           // 12 Jan -> 4 Sep, IFA Berlin
            this.GATE_WEEK = 12;          // week-12 stage-gate

            // The latest defensible freeze: leaves the 18-week build to finish before week 34.
            this.LATEST_FREEZE = this.IFA_WEEK - this.BUILD_WEEKS;   // = 16
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    novelty: 30,        // how new the concept is (0-100)
                    useful: 30,         // how buildable & valuable (0-100)
                    motivation: 55,     // intrinsic drive of the pod (0-100)
                    proto: 40,          // prototype readiness for 4 Sep (0-100)
                    budgetUsed: 0,      // GBP M of development budget committed
                    starKept: true,     // is the abrasive star still on the pod
                    overControlled: false,
                    neverFroze: false,
                    cashReward: false,
                    noveltyHistory: [30],
                    usefulHistory: [30],
                    motivationHistory: [55],
                    protoHistory: [40],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    blend: `generators`,
                    star: `include`,
                    cover: `ignore`,
                    dial: 50,
                    brief: `blank`,
                    reward: `cash`,
                    diverge: 4,
                    converge: 3,
                    validate: 3,
                    freeze: 10,
                    portfolio: `one`,
                    pitch: `novelonly`,
                    ultimatum: `capitulate`,
                    protoInvest: 0,
                    commit: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const bl = document.getElementById(`blendInput`);
                const st = document.getElementById(`starInput`);
                const cv = document.getElementById(`coverInput`);
                if (bl) decisions.blend = bl.value;
                if (st) decisions.star = st.value;
                if (cv) decisions.cover = cv.value;
                if (!decisions.blend || !decisions.star || !decisions.cover) {
                    warn(`warn_r1_incomplete`); return false;
                }
            } else if (round === 2) {
                const di = document.getElementById(`dialInput`);
                const br = document.getElementById(`briefInput`);
                const rw = document.getElementById(`rewardInput`);
                if (di) decisions.dial = parseInt(di.value, 10);
                if (br) decisions.brief = br.value;
                if (rw) decisions.reward = rw.value;
                if (!Number.isFinite(decisions.dial) || decisions.dial < 0 || decisions.dial > 100) {
                    warn(`warn_dial_range`); return false;
                }
            } else if (round === 3) {
                const dv = document.getElementById(`divergeInput`);
                const cg = document.getElementById(`convergeInput`);
                const vl = document.getElementById(`validateInput`);
                const fz = document.getElementById(`freezeInput`);
                const pf = document.getElementById(`portfolioInput`);
                if (dv) decisions.diverge = parseInt(dv.value, 10);
                if (cg) decisions.converge = parseInt(cg.value, 10);
                if (vl) decisions.validate = parseInt(vl.value, 10);
                if (fz) decisions.freeze = parseInt(fz.value, 10);
                if (pf) decisions.portfolio = pf.value;
                const parts = [decisions.diverge, decisions.converge, decisions.validate];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = decisions.diverge + decisions.converge + decisions.validate;
                if (total !== this.FRONT_END) {
                    warn(`warn_alloc_total`); return false;
                }
                if (!Number.isFinite(decisions.freeze) || decisions.freeze < 6 || decisions.freeze > 16) {
                    warn(`warn_freeze_range`); return false;
                }
            } else if (round === 4) {
                const pt = document.getElementById(`pitchInput`);
                const ul = document.getElementById(`ultimatumInput`);
                const pi = document.getElementById(`protoInvestInput`);
                const cm = document.getElementById(`commitInput`);
                if (pt) decisions.pitch = pt.value;
                if (ul) decisions.ultimatum = ul.value;
                if (pi) decisions.protoInvest = parseFloat(pi.value);
                if (cm) decisions.commit = parseInt(cm.value, 10);
                if (!Number.isFinite(decisions.protoInvest) || decisions.protoInvest < 0) {
                    warn(`warn_proto_value`); return false;
                }
                if (!Number.isFinite(decisions.commit) || decisions.commit < 0 || decisions.commit > 100) {
                    warn(`warn_commit_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let novDelta = 0, useDelta = 0, motDelta = 0, protoDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Compose the pod — divergent/convergent blend (Common Error 1: all-stars, no finishers).
                switch (d.blend) {
                    case `balanced`:
                        novDelta += 12; useDelta += 12; protoDelta += 8; coachKey = `coach_r1_balanced`; break;
                    case `generators`:
                        // Dazzling but unbuildable: novelty soars, usefulness & prototype crater.
                        novDelta += 22; useDelta -= 12; protoDelta -= 16; coachKey = `coach_r1_generators`; break;
                    case `finishers`:
                        // Ships the mundane: buildable but flat novelty.
                        novDelta -= 12; useDelta += 14; protoDelta += 12; coachKey = `coach_r1_finishers`; break;
                }

                // The brilliant-but-abrasive star: raises the novelty ceiling, risks motivation.
                if (d.star === `include`) {
                    ds.starKept = true;
                    novDelta += 10; motDelta -= 4;
                } else {
                    ds.starKept = false;
                    novDelta -= 6; motDelta += 4;
                }

                // Cover the missing capability (a manufacturing-savvy finisher closes the build gap).
                switch (d.cover) {
                    case `hire`:
                        spend += 0.3; useDelta += 8; protoDelta += 8; break;
                    case `stretch`:
                        useDelta += 2; protoDelta += 1; break;
                    case `ignore`:
                        useDelta -= 4; protoDelta -= 5; if (coachKey === `coach_default`) coachKey = `coach_r1_gap`; break;
                }

                summaryKey = (d.blend === `balanced`) ? `sum_r1_good` :
                             (d.blend === `generators` ? `sum_r1_allstars` : `sum_r1_safe`);
            } else if (round === 2) {
                // Set the freedom-vs-focus dial (Common Errors 2 & 3: max freedom vs over-control).
                // Optimum is a calibrated middle, ~40-65. Both extremes punish.
                const dial = d.dial;
                if (dial <= 20) {
                    // Maximal freedom: energised but un-aligned; usefulness & prototype suffer.
                    novDelta += 8; useDelta -= 10; protoDelta -= 10; motDelta += 4; coachKey = `coach_r2_freedom`;
                } else if (dial >= 80) {
                    // Over-control: schedule looks safe, but crowds out the creativity the date depends on.
                    ds.overControlled = true;
                    novDelta -= 12; useDelta += 4; protoDelta += 6; motDelta -= 16; coachKey = `coach_r2_control`;
                } else if (dial >= 38 && dial <= 65) {
                    // Calibrated middle — autonomy within a sharp constraint.
                    novDelta += 8; useDelta += 8; protoDelta += 5; motDelta += 2; coachKey = `coach_r2_calibrated`;
                } else {
                    // Off-centre but not extreme.
                    novDelta += 3; useDelta += 2; protoDelta += 2;
                }

                // A sharp creative brief beats both a blank page and a locked spec.
                switch (d.brief) {
                    case `sharp`:
                        novDelta += 6; useDelta += 8; protoDelta += 6; motDelta += 4; coachKey = `coach_r2_sharp`; break;
                    case `blank`:
                        useDelta -= 8; protoDelta -= 8; coachKey = `coach_r2_blank`; break;
                    case `spec`:
                        ds.overControlled = true;
                        novDelta -= 10; motDelta -= 10; useDelta += 3; coachKey = `coach_r2_spec`; break;
                }

                // Reward design — protect intrinsic motivation (Common Error 4: controlling cash prizes).
                switch (d.reward) {
                    case `intrinsic`:
                        motDelta += 12; novDelta += 4; coachKey = (d.brief === `sharp`) ? `coach_r2_intrinsic` : coachKey; break;
                    case `cash`:
                        // The work becomes about the prize; people guard ideas instead of sharing them.
                        ds.cashReward = true;
                        motDelta -= 10; novDelta -= 8; useDelta -= 4; coachKey = `coach_r2_cash`; break;
                    case `none`:
                        motDelta -= 2; break;
                }

                summaryKey = (dial >= 38 && dial <= 65 && d.brief === `sharp` && d.reward === `intrinsic`) ? `sum_r2_good` :
                             (ds.overControlled ? `sum_r2_control` : (dial <= 20 ? `sum_r2_freedom` : `sum_r2_weak`));
            } else if (round === 3) {
                // Allocate the front-end weeks (Common Error 5: never freeze).
                const dv = d.diverge, cg = d.converge, vl = d.validate;

                // Diverge fuels novelty; converge turns ideas into usefulness; validate proves novel-and-useful.
                novDelta += dv * 3 - 4;                 // need some diverge or novelty stalls
                useDelta += cg * 3 + vl * 2 - 5;        // converge + validate build usefulness
                // Balance bonus: a sensible spread (each phase >=2) gets a coherence bump.
                if (dv >= 2 && cg >= 2 && vl >= 2) { novDelta += 4; useDelta += 6; protoDelta += 4; }
                // Starving any phase hurts.
                if (cg === 0 || vl === 0) { useDelta -= 8; coachKey = `coach_r3_noconverge`; }
                if (dv === 0) { novDelta -= 10; coachKey = `coach_r3_nodiverge`; }
                if (dv >= 7) { useDelta -= 6; protoDelta -= 6; coachKey = `coach_r3_overdiverge`; }

                // The freeze decision against the 18-week build.
                const freeze = d.freeze;
                if (freeze > this.LATEST_FREEZE) {
                    // Froze too late (or never): the build has no time; forced into a refresh.
                    ds.neverFroze = true;
                    protoDelta -= 22; novDelta -= 4; coachKey = `coach_r3_late`;
                } else if (freeze <= 7) {
                    // Froze too early: plenty of build time, but you shipped a refresh.
                    novDelta -= 12; protoDelta += 6; coachKey = `coach_r3_early`;
                } else {
                    // Defensible freeze inside the window (weeks 8-16): protects the build AND the novelty.
                    protoDelta += 14; useDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r3_freeze`;
                }

                // Portfolio: a small portfolio into validation beats one early bet or carrying everything.
                switch (d.portfolio) {
                    case `small`:
                        novDelta += 4; useDelta += 6; coachKey = (freeze > 7 && freeze <= this.LATEST_FREEZE) ? `coach_r3_portfolio` : coachKey; break;
                    case `one`:
                        useDelta -= 4; novDelta -= 2; break;
                    case `many`:
                        // Carrying 5+ concepts deep is itself a failure to converge / freeze.
                        protoDelta -= 8; useDelta -= 6; if (!ds.neverFroze) coachKey = `coach_r3_many`; break;
                }

                summaryKey = (dv >= 2 && cg >= 2 && vl >= 2 && freeze > 7 && freeze <= this.LATEST_FREEZE && d.portfolio === `small`) ? `sum_r3_good` :
                             (ds.neverFroze ? `sum_r3_late` : (freeze <= 7 ? `sum_r3_early` : `sum_r3_weak`));
            } else if (round === 4) {
                // The week-12 gate: novel AND useful, motivated team, credible prototype path.
                switch (d.pitch) {
                    case `both`:
                        novDelta += 8; useDelta += 8; protoDelta += 6; coachKey = `coach_r4_both`; break;
                    case `novelonly`:
                        // Unbuildable art — the gate fails the usefulness test.
                        novDelta += 4; useDelta -= 12; coachKey = `coach_r4_novelonly`; break;
                    case `usefulonly`:
                        // Another safe refresh — the gate fails the novelty test.
                        useDelta += 6; novDelta -= 12; coachKey = `coach_r4_usefulonly`; break;
                }

                // Proof-of-concept investment evidences the path to 4 September.
                spend += d.protoInvest;
                if (d.protoInvest >= 0.8) { protoDelta += 18; useDelta += 4; }
                else if (d.protoInvest >= 0.4) { protoDelta += 9; }
                else { protoDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_noproto` : coachKey; }

                // The star designer's ultimatum (Common Error 6: capitulate or fire without weighing the work).
                switch (d.ultimatum) {
                    case `separate`:
                        // Judge the idea on novel-and-useful evidence; keep the person if you can.
                        motDelta += 8; novDelta += 4; useDelta += 4; coachKey = `coach_r4_separate`; break;
                    case `capitulate`:
                        // The pod resents being overruled; the chosen concept may be unvalidated.
                        motDelta -= 12; useDelta -= 6; coachKey = `coach_r4_capitulate`; break;
                    case `fire`:
                        // The boldest, most novel idea walks out with them.
                        ds.starKept = false;
                        novDelta -= 14; motDelta -= 6; coachKey = `coach_r4_fire`; break;
                }

                // Commitment to the week-12-to-4-Sep timeline.
                if (d.commit >= 60) { protoDelta += 6; }
                else if (d.commit <= 25) { protoDelta -= 6; motDelta -= 2; }

                summaryKey = (d.pitch === `both` && d.ultimatum === `separate` && d.protoInvest >= 0.4) ? `sum_r4_good` :
                             (d.pitch === `novelonly` ? `sum_r4_novel` : (d.pitch === `usefulonly` ? `sum_r4_useful` : `sum_r4_weak`));
            }

            // Resource accounting: development budget (GBP 2.4M cap).
            ds.budgetUsed = Math.min(this.DEV_BUDGET, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Apply deltas, clamp 0-100.
            ds.novelty = Math.max(0, Math.min(100, Math.round(ds.novelty + novDelta)));
            ds.useful = Math.max(0, Math.min(100, Math.round(ds.useful + useDelta)));
            ds.motivation = Math.max(0, Math.min(100, Math.round(ds.motivation + motDelta)));
            ds.proto = Math.max(0, Math.min(100, Math.round(ds.proto + protoDelta)));

            ds.noveltyHistory.push(ds.novelty);
            ds.usefulHistory.push(ds.useful);
            ds.motivationHistory.push(ds.motivation);
            ds.protoHistory.push(ds.proto);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                novelty: ds.novelty,
                noveltyDelta: Math.round(novDelta),
                useful: ds.useful,
                usefulDelta: Math.round(useDelta),
                motivation: ds.motivation,
                motivationDelta: Math.round(motDelta),
                proto: ds.proto,
                protoDelta: Math.round(protoDelta),
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _fmtMoney(v) {
            // Locale-aware GBP: English "£2.40M", Spanish "2,40 M£".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} M£`;
            }
            return `${sign}£${abs.toFixed(2)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const lowHigh = (selector, v) => {
                const card = document.querySelector(selector);
                if (card) {
                    card.classList.toggle(`sparksim-card-low`, Number(v) <= 25);
                    card.classList.toggle(`sparksim-card-high`, Number(v) >= 75);
                }
            };

            uiManager.bind(`noveltyDisplay`, `domainState.novelty`, (v) => { lowHigh(`.sparksim-card-novelty`, v); return Math.round(Number(v)); });
            uiManager.bind(`usefulDisplay`, `domainState.useful`, (v) => { lowHigh(`.sparksim-card-useful`, v); return Math.round(Number(v)); });
            uiManager.bind(`motivationDisplay`, `domainState.motivation`, (v) => { lowHigh(`.sparksim-card-motivation`, v); return Math.round(Number(v)); });
            uiManager.bind(`protoDisplay`, `domainState.proto`, (v) => { lowHigh(`.sparksim-card-proto`, v); return Math.round(Number(v)); });

            const self = this;
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.DEV_BUDGET);
            });

            // Dial slider readout.
            const di = document.getElementById(`dialInput`);
            const diReadout = document.getElementById(`dialReadout`);
            if (di && diReadout) {
                diReadout.textContent = di.value;
                di.addEventListener(`input`, function() { diReadout.textContent = di.value; });
            }

            // Freeze slider readout.
            const fz = document.getElementById(`freezeInput`);
            const fzReadout = document.getElementById(`freezeReadout`);
            if (fz && fzReadout) {
                fzReadout.textContent = fz.value;
                fz.addEventListener(`input`, function() { fzReadout.textContent = fz.value; });
            }

            // Front-end weeks live total (must hit 10).
            const allocIds = [`divergeInput`, `convergeInput`, `validateInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.sparksim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.FRONT_END) ? `#dc2626` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

