        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.noveltyHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                sparkChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.noveltyHistory },
                        { data: ds.usefulHistory },
                        { data: ds.motivationHistory },
                        { data: ds.protoHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const novelty = Math.round(ds.novelty);
            const useful = Math.round(ds.useful);
            const motivation = Math.round(ds.motivation);
            const proto = Math.round(ds.proto);
            const creative = Math.min(novelty, useful);
            return Math.round(creative * 0.34 + ((novelty + useful) / 2) * 0.16 + motivation * 0.25 + proto * 0.25);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const novelty = Math.round(ds.novelty);
            const useful = Math.round(ds.useful);
            const motivation = Math.round(ds.motivation);
            const proto = Math.round(ds.proto);

            // Creativity is novel AND useful — score the WEAKER of the two harder (min-weighted).
            const creative = Math.min(novelty, useful);
            const composite = this._composite(ds);

            // The week-12 gate passes only on all four conditions.
            const isNovel = novelty >= 55;
            const isUseful = useful >= 55;
            const motivated = motivation >= 50;
            const onTrack = proto >= 55;
            const gatePassed = isNovel && isUseful && motivated && onTrack;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_cancelled`;
            if (gatePassed && composite >= 75) tierKey = `grade_breakthrough`;
            else if (gatePassed) tierKey = `grade_gate`;
            else if (isUseful && !isNovel) tierKey = `grade_safe`;
            else if (isNovel && !isUseful) tierKey = `grade_art`;
            else if (!motivated) tierKey = `grade_burnout`;
            else if (composite >= 50) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (gatePassed) insights.push(window.mySimulation.t(`insight_gate`));
            else if (isUseful && !isNovel) insights.push(window.mySimulation.t(`insight_refresh`));
            else if (isNovel && !isUseful) insights.push(window.mySimulation.t(`insight_art`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!motivated) insights.push(window.mySimulation.t(`insight_motivation`));
            if (ds.cashReward) insights.push(window.mySimulation.t(`insight_cash`));
            if (ds.overControlled) insights.push(window.mySimulation.t(`insight_control`));
            if (ds.neverFroze) insights.push(window.mySimulation.t(`insight_freeze`));
            if (!ds.starKept) insights.push(window.mySimulation.t(`insight_star`));
            if (gatePassed && composite >= 75) insights.push(window.mySimulation.t(`insight_breakthrough`));

            return {
                novelty: novelty,
                useful: useful,
                motivation: motivation,
                proto: proto,
                creative: creative,
                isNovel: isNovel,
                isUseful: isUseful,
                motivated: motivated,
                onTrack: onTrack,
                gatePassed: gatePassed,
                starKept: !!ds.starKept,
                overControlled: !!ds.overControlled,
                cashReward: !!ds.cashReward,
                budgetUsed: ds.budgetUsed,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="sp-cm"><p class="sp-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="sp-cm-chip ` + (ok ? `sp-cm-ok` : `sp-cm-no`) + `">` +
                `<span class="sp-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="sp-cm-kpi"><div class="sp-cm-kpi-val">` + val +
                `</div><div class="sp-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="sp-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="sp-cm">` +
  `<div class="sp-cm-head">` +
    `<div class="sp-cm-score"><div class="sp-cm-score-num">` + Math.round(s.composite) +
       `<span class="sp-cm-score-den">/100</span></div>` +
       `<div class="sp-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="sp-cm-verdict"><div class="sp-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="sp-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="sp-cm-section"><div class="sp-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="sp-cm-chips">` + chip(!!s.isNovel, t(`cm_t_novel`)) + chip(!!s.isUseful, t(`cm_t_useful`)) +
      chip(!!s.motivated, t(`cm_t_motivated`)) + chip(!!s.onTrack, t(`cm_t_ontrack`)) + `</div></div>` +
  `<div class="sp-cm-section"><div class="sp-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="sp-cm-kpis">` +
      kpi(t(`novelty_label`), Math.round(s.novelty), t(`cm_sub_novelty`)) +
      kpi(t(`useful_label`), Math.round(s.useful), t(`cm_sub_useful`)) +
      kpi(t(`motivation_label`), Math.round(s.motivation), t(`cm_sub_motivation`)) +
      kpi(t(`proto_label`), Math.round(s.proto), t(`cm_sub_proto`)) +
    `</div></div>` +
  (insights ? `<div class="sp-cm-section"><div class="sp-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="sp-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
