        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.neverFroze) return window.mySimulation.t(`hint_freeze`);
            if (ds.overControlled && ds.motivation < 45) return window.mySimulation.t(`hint_control`);
            if (ds.cashReward) return window.mySimulation.t(`hint_cash`);
            if (ds.novelty >= 60 && ds.useful <= 35) return window.mySimulation.t(`hint_art`);
            if (ds.useful >= 60 && ds.novelty <= 35) return window.mySimulation.t(`hint_refresh`);
            if (state.currentPeriod >= 3 && ds.proto < 40) return window.mySimulation.t(`hint_proto`);
            if (ds.novelty >= 60 && ds.useful >= 60 && ds.motivation >= 55 && ds.proto >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

